import{_ as e,o as t,c as o,a3 as l}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"工具与 MCP","description":"从通用工具调用协议进入 LangChain Tools，再扩展到 MCP 协议与适配。","frontmatter":{"title":"工具与 MCP","description":"从通用工具调用协议进入 LangChain Tools，再扩展到 MCP 协议与适配。"},"headers":[],"relativePath":"py-agent/agent/tools-mcp/index.md","filePath":"py-agent/agent/tools-mcp/index.md","lastUpdated":1785314595000}'),n={name:"py-agent/agent/tools-mcp/index.md"};function i(r,a,p,c,s,h){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="工具与-mcp" tabindex="-1">工具与 MCP <a class="header-anchor" href="#工具与-mcp" aria-label="Permalink to &quot;工具与 MCP&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>工具把模型的结构化请求连接到真实应用能力，MCP 则把能力发现与调用扩展到进程和服务边界。本分组始终区分模型请求、应用校验、实际执行和结果回传四个阶段。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>解释模型工具调用协议及其执行边界；</li><li>使用 LangChain 定义同步、异步和运行时感知工具；</li><li>为工具设计参数、错误、副作用和授权契约；</li><li>理解 MCP Host、Client、Server 与三类原语；</li><li>把 MCP Server 的工具接入 LangChain Agent，并处理会话与错误边界。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/agent/tools-mcp/tool-calling">工具调用</a>：框架无关的请求、校验、执行和回传协议。</li><li><a href="/py-agent/agent/tools-mcp/langchain-tools">LangChain Tools</a>：工具定义 API 与运行时能力。</li><li><a href="/py-agent/agent/tools-mcp/mcp-protocol">MCP 协议</a>：架构、原语、传输、生命周期和安全。</li><li><a href="/py-agent/agent/tools-mcp/mcp-langchain">MCP 与 LangChain</a>：客户端配置、工具加载、会话和内容映射。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>MCP 不等于 Agent，也不替工具执行授权。本组讲清协议和集成，不展开远程服务部署、企业身份治理和跨网络生产运维。</p>',10)])])}const _=e(n,[["render",i]]);export{g as __pageData,_ as default};
